style.css:
@-moz-document domain("rotorburn.com") {
:root {
        color-scheme: dark;
        --dark-bg: #101113;
        --dark-panel: #1b1d20;
        --dark-panel-alt: #222428;
        --dark-panel-raised: #292b30;
        --dark-header: #303136;
        --dark-input: #25272b;
        --dark-border: #393b41;
        --dark-border-soft: #303238;
        --dark-text: #e8e8ea;
        --dark-muted: #b4b6bd;
        --dark-faint: #9497a0;
        --dark-accent: #ff5b5e;
        --dark-accent-hover: #ff9a9a;
        --dark-link: #e47578;
        --dark-focus: rgba(255, 91, 94, .32);
        --dark-selection: #49282e;
        --dark-success: #a4e0b2;
    }

    /* 02. Page background, page chrome and navigation. */
    html, body { background: var(--dark-bg); color: var(--dark-text); }
    .p-pageWrapper {
        color: var(--dark-text);
        background: linear-gradient(rgba(7, 8, 10, .66), rgba(7, 8, 10, .82)),
                    #000 url("https://images.pexels.com/photos/20411229/pexels-photo-20411229.jpeg") center center / cover fixed no-repeat;
        min-height: 100vh;
    }
    .p-header, .p-nav, .p-navSticky, .p-sectionLinks, .p-footer,
    .p-footer-inner, .p-navEl-splitTrigger, .p-nav-opposite .p-navgroup {
        color: var(--dark-text);
        background-color: var(--dark-panel);
    }
    .p-header { background-color: rgba(20, 21, 24, .90); }
    .p-nav, .p-navSticky { background-color: rgba(25, 26, 30, .96); }
    .p-sectionLinks { background: var(--dark-panel-alt); border-bottom: 1px solid var(--dark-border); }
    .p-footer, .p-footer-inner { background-color: #17181b; }
    .p-footer a, .p-header a, .p-nav a, .p-sectionLinks a { color: var(--dark-text); }
    .p-nav a:hover, .p-sectionLinks a:hover, .p-footer a:hover { color: var(--dark-accent-hover); }
    .p-navEl.is-selected, .p-navEl.is-menuOpen, .p-navEl-link:hover,
    .p-navEl-splitTrigger:hover, .p-sectionLinks-list a:hover {
        background-color: var(--dark-panel-raised);
        color: var(--dark-text);
    }
    .p-body-header, .p-description, .p-body-pageContent, .p-body-sidebar,
    .p-breadcrumbs, .p-breadcrumbs a, .p-body-header .p-title-value { color: var(--dark-text); }
    .p-description, .p-breadcrumbs, .p-breadcrumbs a, .p-body-header .p-title-pageAction { color: var(--dark-muted); }
    .p-body-content, .p-body-sideNav { color: var(--dark-text); }
    .p-staffBar, .p-staffBar-inner { background: var(--dark-panel-alt); color: var(--dark-text); }

    .porta-article-item .porta-article-date .porta-date-block { background: var(--dark-header); border: 1px solid #4b4b4b; }
    .porta-block-icon { background: #1b1d20; border: none; }

    /* Accessible default links; preserve white text for explicitly filled buttons. */
    a { color: var(--dark-link); }
    a:hover { color: var(--dark-accent-hover); text-decoration: underline; }
    a:focus-visible, button:focus-visible, .button:focus-visible,
    .input:focus-visible, select:focus-visible, textarea:focus-visible {
        outline: 2px solid var(--dark-accent);
        outline-offset: 2px;
    }
    ::selection { color: #fff; background: var(--dark-selection); }
    ::-moz-selection { color: #fff; background: var(--dark-selection); }

    /* 03. Blocks, forum/category rows and sidebar. */
    .block-container, .block--messages .block-container {
        color: var(--dark-text);
        background: var(--dark-panel);
        border: 1px solid var(--dark-border-soft);
        border-radius: 6px;
    }
    .block--messages .block-container { background: transparent; border: 0; }
    .block-header, .block-minorHeader, .block-tabHeader, .block-outer-opposite,
    .block-outer-main, .block-formSectionHeader {
        color: var(--dark-text);
        background: var(--dark-header);
        border-color: var(--dark-border);
        border-radius: 3px;
    }
    .block-header { background: var(--dark-header); font-weight: 500; border-bottom: 1px solid var(--dark-border); }
    .block-header a, .block-minorHeader a { color: var(--dark-text); text-decoration: none; }
    .block-header a:hover, .block-minorHeader a:hover { color: var(--dark-accent-hover); }
    .block-body, .block-row, .block-rowMessage { background: var(--dark-panel); color: var(--dark-text); }
    .block-row.block-row--alt, .block-row--separated, .block-row.block-row--clickable:hover,
    .block-row:hover.block-row--clickable { background: var(--dark-panel-alt); }
    .block-row + .block-row, .block-row--separated, .block-body + .block-body,
    .block-row + .block-minorHeader { border-color: var(--dark-border-soft); }
    .block-filterBar, .block-filterBar.block-filterBar--standalone {
        color: var(--dark-text);
        background: var(--dark-panel-alt);
        border-bottom: 1px solid var(--dark-border);
    }
    .block-filterBar a { color: var(--dark-link); }
    .block-footer, .block-footer:before {
        color: var(--dark-muted);
        background: var(--dark-panel-alt);
        border-color: var(--dark-border);
        background-image: none;
    }
    .block-footer a { color: var(--dark-link); }
    .block-textHeader, .block-textHeader a, .block-rowMessage a { color: var(--dark-text); }
    .block-outer, .block-outer-opposite, .block-outer-main { color: var(--dark-muted); }
    .node + .node, .structItem, .structItem + .structItem,
    .structItemContainer .structItem, .contentRow + .contentRow { border-color: var(--dark-border); }
    .node, .node-body, .node-description, .node-stats, .node-extra,
    .structItem, .structItem-cell, .structItem-title, .structItem-minor,
    .contentRow, .contentRow-main, .contentRow-header, .contentRow-lesser,
    .contentRow-minor { color: var(--dark-text); }
    .node-description, .node-stats, .node-extra, .structItem-minor,
    .contentRow-lesser, .contentRow-minor, .pairs dt, .pairs--rows dt,
    .u-muted, .u-dimmed, .minor { color: var(--dark-muted); }
    .node-title a, .structItem-title a, .contentRow-header a { color: var(--dark-text); }
    .node-title a:hover, .structItem-title a:hover, .contentRow-header a:hover { color: var(--dark-accent-hover); }
    .node-icon, .node-icon i, .structItem-cell--icon i { color: var(--dark-accent); }
    .structItem.is-unread, .structItem.is-unread .structItem-cell { background: #ffffff07; }
    .node.node--unread, .node.node--unread .node-body { background: #ffffff07; }

    .formRow>dt {
        background: var(--dark-panel);
        border-right: 1px solid transparent;
        border-color: var(--dark-border);
    }
    .blockLink.is-selected {
        background: var(--dark-panel-raised);
        border-left: 3px solid var(--dark-border);
    }
    .blockLink:hover {
        background: #f5f5f53b;
    }
    .blockStatus {
        color: var(--dark-text);
        background: var(--dark-panel-raised);
        border-top-color: var(--dark-border);
        border-right-color: var(--dark-border);
        border-bottom-color: var(--dark-border);
        border-left-color: var(--dark-accent);
        border-left: 3px solid var(--dark-accent);
    }

    /* 04. Tabs, page navigation and breadcrumbs. */
    .tabs, .tabs-tab, .tabs--standalone, .tabs-container, .block-tabHeader {
        color: var(--dark-muted);
        background: var(--dark-panel-alt);
        border-color: var(--dark-border);
    }
    .tabs-tab:hover, .tabs-tab.is-active, .tabs-tab.is-selected,
    .block-tabHeader .tabs-tab.is-active { color: var(--dark-text); border-color: var(--dark-accent); }
    .pageNav, .pageNav-main, .pageNav-page, .pageNav-jump,
    .pageNav-page.pageNav-page--current {
        color: var(--dark-text);
        background: var(--dark-panel-alt);
        border: 0px solid var(--dark-border);
        border-radius: 3px;
    }
    .pageNav-page a, .pageNav-jump a { color: inherit; }
    .pageNav-page:not(:first-child) { border-left-color: var(--dark-border); }
    .pageNav-page.pageNav-page--current {
        color: #fff;
        background: #633338;
        border-color: var(--dark-accent);
    }
    .pageNav-page:hover, .pageNav-jump:hover { background: var(--dark-panel-raised); color: #fff; text-decoration: none; }
    .pageNav-page--current:hover { background: #783c42; }
    .pageNavSimple-el, .pageNavSimple-el--current { color: var(--dark-text); background: var(--dark-panel-alt); border-color: var(--dark-border); }

    /* 05. Buttons, text fields and form layouts. */
    .button, a.button, button.button, input.button {
        color: var(--dark-text);
        background: #303238;
        border: 1px solid #484a52;
        border-radius: 4px;
        transition: background-color .125s ease, border-color .125s ease, color .125s ease;
    }
    .button:hover, a.button:hover, button.button:hover, input.button:hover,
    .button:focus, .button:active { color: #fff; background: #44464d; border-color: #62656d; text-decoration: none; }
    .button.button--primary, a.button.button--primary, .button.button--cta, a.button.button--cta {
        color: #fff;
        background: #a7353b;
        border-color: #c3464b;
    }
    .button.button--primary:hover, a.button.button--primary:hover,
    .button.button--cta:hover, a.button.button--cta:hover {
        color: #fff; background: #c0444a; border-color: var(--dark-accent);
    }
    .button.button--link, a.button.button--link { color: var(--dark-text); background: #34363c; border: 1px solid var(--dark-border); }
    .button.button--link:hover, a.button.button--link:hover,
    .button.button--link:active, a.button.button--link:active,
    .button.button--link:focus, a.button.button--link:focus { background: #474951; color: #fff; text-decoration: none; }
    .button.is-disabled, .button:disabled, button:disabled { opacity: .55; }
    .input, input.input, textarea.input, select.input, .inputGroup.inputGroup--joined .inputGroup-text,
    .inputGroup-text, .inputGroup .input, .inputGroup input, .inputGroup textarea {
        color: var(--dark-text);
        background: var(--dark-input);
        border: 1px solid #4b4d55;
        border-radius: 4px;
    }
    .input:focus, textarea.input:focus, select.input:focus,
    .inputGroup input:focus, .inputGroup textarea:focus {
        color: #fff;
        background: #2a2c31;
        border-color: var(--dark-accent);
        box-shadow: 0 0 0 3px var(--dark-focus);
    }
    .input::placeholder, .inputGroup input::placeholder, textarea::placeholder { color: var(--dark-faint); opacity: 1; }
    .inputGroup.inputGroup--joined .inputGroup-text, .inputGroup-text { background: #35373e; color: var(--dark-text); }
    .inputGroup.inputGroup--joined .inputGroup-text { border-color: #4b4d55; }
    .inputGroup-text a, .inputGroup-text button { color: var(--dark-text); }
    .formRow, .formRow-label, .formRow-explain, .formRow-hint,
    .formRow .formRow-label, .formRow .formRow-explain { color: var(--dark-text); }
    .formRow-explain, .formRow-hint, .formRow .formRow-explain { color: var(--dark-muted); }
    .formRow + .formRow, .formRowSep, .formRow--input, .formSubmitRow { border-color: var(--dark-border); }
    .formSubmitRow, .formSubmitRow-bar, .formInfoRow { color: var(--dark-text); background: var(--dark-panel-alt); border-color: var(--dark-border); }
    .formRow label, .inputChoices, .inputChoices-choice, .iconic { color: var(--dark-text); }
    input[type="checkbox"], input[type="radio"] { accent-color: var(--dark-accent); }
    input:-webkit-autofill, textarea:-webkit-autofill, select:-webkit-autofill {
        -webkit-text-fill-color: var(--dark-text);
        -webkit-box-shadow: 0 0 0 1000px var(--dark-input) inset;
    }

    /* 06. Menus, overlays, member cards and dialogs. */
    .menu, .menu-content, .menu-row, .menu-footer, .menu-header,
    .overlay, .overlay-container, .overlay-content, .overlay-title,
    .tooltip-content, .memberTooltip, .memberTooltip-content,
    .acp-menu, .select2-dropdown, .select2-results__option {
        color: var(--dark-text);
        background: var(--dark-panel-alt);
        border-color: var(--dark-border);
    }
    .menu-content, .overlay-container, .tooltip-content { border: 1px solid var(--dark-border); box-shadow: 0 16px 40px rgba(0, 0, 0, .55); }
    .menu-header, .menu-footer, .overlay-title { background: var(--dark-header); border-color: var(--dark-border); }
    .menu-linkRow, .menu-linkRow:link, .menu-linkRow:visited, .menu-row a,
    .menu-tab, .menu-footer a { color: var(--dark-text); }
    .menu-linkRow:hover, .menu-linkRow.is-selected, .menu-row:hover,
    .menu-tab:hover, .menu-tab.is-active { color: #fff; background: #3a3035; }
    .menu-separator, .menu-row + .menu-row { border-color: var(--dark-border); }
    .select2-container--default .select2-selection--single,
    .select2-container--default .select2-selection--multiple,
    .select2-container--default .select2-search--dropdown .select2-search__field {
        color: var(--dark-text); background: var(--dark-input); border-color: var(--dark-border);
    }
    .select2-container--default .select2-results__option--highlighted[aria-selected] { color: #fff; background: #7b353c; }

    .userBanner.userBanner--staff::before {
        content: "\1F451";
        margin-right: 2px;
        font-size: 10px;
        vertical-align: 1px;
    }
    .userBanner.userBanner--staff, .userBanner.userBanner--primary {
        color: var(--dark-text);
        background: var(--dark-panel-raised);
        border-color: #dcdcdc;
        border-color: var(--dark-border);
    }

    /* 07. Message/post surfaces and their author column (from message.less). */
    .block--messages .message, .block--messages .block-row, .message {
        color: var(--dark-text);
        background: var(--dark-panel);
        border-color: var(--dark-border);
    }
    .message + .message, .message.message--bordered, .message-inner + .message-inner { border-color: var(--dark-border); }
    .message-cell.message-cell--main, .message-main, .message-content,
    .message-body, .message-signature, .message-footer { color: var(--dark-text); }
    .message-cell.message-cell--user, .message-cell.message-cell--action,
    .message-cell.message-cell--vote, .message-cell.message-cell--extra {
        color: var(--dark-text);
        background: var(--dark-panel-alt);
        border-color: var(--dark-border);
    }
    .message-cell.message-cell--header { color: var(--dark-text); background: var(--dark-header); background-image: none; border-color: var(--dark-border); }
    .message-userArrow { border-right-color: var(--dark-border); }
    .message-userArrow:after { border-right-color: var(--dark-panel); }
    .message.is-mod-selected, .block--messages .message.is-mod-selected { background: #292329; }
    .message.is-mod-selected .message-cell--user,
    .block--messages .message.is-mod-selected .message-cell--user,
    .message.is-mod-selected .message-cell--vote { background: #30262d; }
    .message.is-mod-selected .message-userArrow:after,
    .block--messages .message.is-mod-selected .message-userArrow:after { border-right-color: #292329; }
    .message-attribution, .message-signature { color: var(--dark-muted); border-color: var(--dark-border); }
    .message-attribution a, .message-attribution-opposite a { color: var(--dark-muted); }
    .message-attribution-opposite a:hover { color: var(--dark-accent-hover); }
    .message-userTitle, .message-userExtras, .message-lastEdit,
    .message-articleWrittenBy, .message-articleUserStats, .comment-note { color: var(--dark-muted); }
    .message-avatar-wrapper .message-avatar-online:before { background: var(--dark-panel-alt); border-color: var(--dark-panel-alt); }
    .message-expandLink { background: linear-gradient(to bottom, rgba(27, 29, 32, 0), var(--dark-panel) 70%); }
    .message-expandLink:empty { background: linear-gradient(to bottom, rgba(27, 29, 32, 0), var(--dark-panel)); }
    .message-expandLink a { color: var(--dark-accent-hover); }
    .message-gradient { background: linear-gradient(to bottom, rgba(27, 29, 32, 0), var(--dark-panel) 90%); }
    .message-responseRow, .message-articleUserInfo, .likesBar, .reactionsBar,
    .message-actionBar, .message-footer, .comment-input { border-color: var(--dark-border); }
    .message-responseRow, .message-articleUserInfo, .likesBar, .reactionsBar { color: var(--dark-text); background: var(--dark-panel-alt); }
    .reactionsBar .reactionSummary>li, .message-responseRow .reactionSummary>li {background: #222428;}
    .messageNotice, .messageNotice.messageNotice--highlighted,
    .message-cell.message-cell--alert {
        color: #ffd4d5;
        background: #382429;
        border-color: var(--dark-accent);
    }

    .messageNotice a, .message-cell.message-cell--alert a { color: var(--dark-accent-hover); }
    .message--solution .message-cell.message-cell--vote,
    .message-cell.message-cell--solutionHeader { color: var(--dark-success); background: #203b2c; border-color: #467954; }
    .message--articlePreview, .message--articlePreview .articlePreview-main,
    .message--articlePreview .articlePreview-text { background: var(--dark-panel); color: var(--dark-text); }
    .message--articlePreview .articlePreview-footer, .message--articlePreview .articlePreview-meta { color: var(--dark-muted); border-color: var(--dark-border); }

    /* 08. Quotes, spoilers, inline code, fenced code and syntax highlighting. */
    .bbCodeBlock, .bbCodeBlock.bbCodeBlock--quote, .bbCodeBlock--unfurl {
        color: var(--dark-text);
        background: #24262a;
        border: 1px solid var(--dark-border);
        border-left: 3px solid var(--dark-accent);
    }
    .bbCodeBlock-title { color: var(--dark-accent-hover); background: #303036; }
    .bbCodeBlock-content { color: var(--dark-text); }
    .bbCodeBlock-expandLink { background: linear-gradient(to bottom, rgba(36, 38, 42, 0), #24262a 80%); }
    .bbCodeBlock-expandLink a { color: var(--dark-accent-hover); }
    .bbCodeInline, .bbCodeCode, .bbCodeCode code, code { color: #dbe5f6; }
    .bbCodeInline { background: #303238; border: 1px solid #4a4c54; }
    .bbCodeCode { background: transparent; }
    .bbCodeCode .prism-token.prism-comment, .bbCodeCode .prism-token.prism-prolog,
    .bbCodeCode .prism-token.prism-doctype, .bbCodeCode .prism-token.prism-cdata { color: #a1a7b0; }
    .bbCodeCode .prism-token.prism-constant, .bbCodeCode .prism-token.prism-number { color: #a4dbbb; }
    .bbCodeCode .prism-token.prism-tag, .bbCodeCode .prism-token.prism-attr-name { color: #e9a7a7; }
    .bbCodeCode .prism-token.prism-boolean, .bbCodeCode .prism-token.prism-symbol,
    .bbCodeCode .prism-token.prism-atrule, .bbCodeCode .prism-token.prism-keyword { color: #c9a5ff; }
    .bbCodeCode .prism-token.prism-selector, .bbCodeCode .prism-token.prism-function,
    .bbCodeCode .prism-token.prism-regex, .bbCodeCode .prism-token.prism-variable,
    .bbCodeCode .prism-token.prism-package { color: #9ac9ff; }
    .bbCodeCode .prism-token.prism-string, .bbCodeCode .prism-token.prism-attr-value,
    .bbCodeCode .prism-token.prism-char { color: #edc38c; }
    .bbCodeCode .prism-token.prism-class-name, .bbCodeCode .prism-token.prism-builtin { color: #8cdbdb; }
    .bbCodeCode .prism-token.prism-deleted { color: #ff9696; }
    .bbCodeCode .prism-token.prism-inserted { color: #a4dbbb; }
    .bbCodeCode .prism-token.prism-important, .bbCodeCode .prism-token.prism-bold { color: #f4b5cd; }
    .bbCodeCode .prism-token.prism-entity { color: #dbe5f6; }
    .bbCodeBlock--unfurl .contentRow-snippet, .bbCodeBlock--unfurl .contentRow-minor { color: var(--dark-muted); }

    /* 09. Froala rich-text editor: edit area, toolbar, SVG icons, menus and dialogs. */
    .fr-box.fr-basic, .fr-box.fr-basic.is-focused { background: var(--dark-panel-alt); border: 1px solid var(--dark-border); }
    .fr-box.fr-basic .fr-wrapper, .fr-box.fr-basic.is-focused .fr-wrapper {
        background: var(--dark-input);
        border: 1px solid var(--dark-border);
        border-bottom-color: var(--dark-border);
    }
    .fr-box.fr-basic .fr-element, .fr-element.fr-view, .fr-element,
    .fr-box.fr-basic .fr-element p, .fr-box.fr-basic .fr-element div { color: var(--dark-text); }
    .fr-view blockquote { background: #24262a; border: 1px solid var(--dark-border); border-left: 3px solid var(--dark-accent); }
    .fr-view blockquote[data-quote]:before { color: var(--dark-link); background: #303036 !important; }
    .fr-element { background: transparent; caret-color: var(--dark-text); }
    .fr-wrapper .fr-placeholder { color: var(--dark-faint); }
    .fr-wrapper ::selection { background: #774149; color: #fff; }
    .fr-wrapper ::-moz-selection { background: #774149; color: #fff; }
    .fr-toolbar, .fr-box.fr-basic.is-focused .fr-toolbar.fr-top,
    .fr-popup, .fr-modal, .fr-modal .fr-modal-wrapper,
    .fr-modal .fr-modal-wrapper .fr-modal-head {
        color: var(--dark-text);
        background: #303238;
        border-color: var(--dark-border);
    }
    .fr-toolbar .fr-more-toolbar, .fr-toolbar .fr-command.fr-btn.fr-open:not(:hover):not(:focus):not(:active) {
        color: var(--dark-text);
        background: #3a3c43;
    }
    .fr-toolbar .fr-newline, .fr-separator { background: var(--dark-border); }
    .fr-toolbar .fr-command.fr-btn, .fr-popup .fr-command.fr-btn,
    .fr-modal .fr-command.fr-btn, .fr-command.fr-btn.fr-dropdown.fr-options { color: var(--dark-text); }
    .fr-toolbar .fr-command.fr-btn svg path, .fr-popup .fr-command.fr-btn svg path,
    .fr-modal .fr-command.fr-btn svg path { fill: var(--dark-text); }
    .fr-toolbar .fr-command.fr-btn.fr-dropdown:after,
    .fr-popup .fr-command.fr-btn.fr-dropdown:after,
    .fr-modal .fr-command.fr-btn.fr-dropdown:after { border-top-color: var(--dark-text); }
    .fr-toolbar .fr-command.fr-btn.fr-dropdown.fr-active:after,
    .fr-popup .fr-command.fr-btn.fr-dropdown.fr-active:after { border-bottom-color: var(--dark-text); }
    .fr-desktop .fr-command:hover:not(.fr-table-cell),
    .fr-desktop .fr-command:focus:not(.fr-table-cell),
    .fr-desktop .fr-command.fr-selected:not(.fr-table-cell),
    .fr-desktop .fr-command.fr-btn-hover:not(.fr-table-cell),
    .fr-desktop .fr-command.fr-expanded:not(.fr-table-cell),
    .fr-toolbar .fr-command.fr-btn.fr-btn-active-popup,
    .fr-toolbar .fr-command.fr-btn.fr-dropdown.fr-active,
    .fr-popup .fr-command.fr-btn.fr-dropdown.fr-active,
